function testTotalRainItem() {
  console.log(JSON.stringify(totalRainItem([{ json: { daily: { precipitation_sum: [0, 1.7, 0.4, 0, 2.2, 0, 0] } } }])))
}

function totalRainItem(items) {
  const forecast = items[0].json
  const total = forecast.daily.precipitation_sum.reduce((sum, mm) => sum + mm, 0)
  const totalRain = Math.round(total * 10) / 10
  return [{ json: { totalRain, needsWatering: totalRain < 5 } }]
}
